def word_count(say_list):
    return sum(len(p.split()) for p in say_list)

print("Part 1 words:", word_count(part1_say))
print("Part 2 words:", word_count(part2_say))
print("Part 3 words:", word_count(part3_say))
print("Part 4 words:", word_count(part4_say))
print("Part 5 words:", word_count(part5_say))
total = sum(word_count(p) for p in [part1_say, part2_say, part3_say, part4_say, part5_say])
print("Total words:", total)
assert all(word_count(p) >= 600 for p in [part1_say, part2_say, part3_say, part4_say, part5_say]), "All parts must be >= 600 words"
assert total >= 3100, "Total words must be >= 3100"
print("All word count invariants satisfied!")
